import{_ as s,a0 as l,w as n,s as i,ao as d,I as p,x as a,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"现实中的应用程序是如何丢失数据？ | LCTT x X-CMD","titleTemplate":false,"description":"现实中的应用程序是如何丢失数据？ | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"现实中的应用程序是如何丢失数据？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"现实中的应用程序是如何丢失数据？ | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210606 How Real-World Apps Lose Data","title":"现实中的应用程序是如何丢失数据？","tag":"202107","desc":""},"relativePath":"202107/20210606 How Real-World Apps Lose Data.md","filePath":"[post].md"}'),m={name:"202107/20210606 How Real-World Apps Lose Data.md"};function f(h,t,u,T,x,C){const e=l("Link");return n(),i("div",null,[t[15]||(t[15]=d('<h1 id="现实中的应用程序是如何丢失数据" tabindex="-1">现实中的应用程序是如何丢失数据？ <a class="header-anchor" href="#现实中的应用程序是如何丢失数据" aria-label="Permalink to “现实中的应用程序是如何丢失数据？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/20/062734awvesw2nqnzrsw5i.jpg" alt=""></p><p>现代应用程序开发的一大优点是，像硬件故障或如何设置 RAID 这类问题是由云提供商操心的。优秀的云供应商不太可能丢失你的应用数据，所以有时我会被询问现在为什么还要备份？下面是一些现实世界的故事。</p><h3 id="故事之一" tabindex="-1">故事之一 <a class="header-anchor" href="#故事之一" aria-label="Permalink to “故事之一”">​</a></h3><p>第一个故事来自一个数据科学项目：它基本上是一个从正在进行的研究中来收集数据的庞大而复杂的管道，然后用各种不同的方式处理以满足一些尖端模型的需要。这个面向用户的应用程序还没有推出，但是一个由数据科学家和开发人员组成的团队已经为建立这个模型和它的数据集工作了好几个月。</p><p>在项目中工作的人有他们自己的实验工作的开发环境。他们会在终端中做一些类似 <code>export ENVIRONMENT=simonsdev</code> 的事情，然后所有在终端上运行的软件都会在那个环境下运行，而不是在生产环境下。</p><p>该团队迫切需要推出一个面向用户的应用程序，以便那些花钱的人能够从他们几个月的投资中真正看到一些回报。在一个星期六，一位工程师试图赶工一些工作。他在晚上很晚的时候做完了一个实验，决定收拾东西回家。他启动了一个清理脚本来删除他的开发环境中的所有内容，但奇怪的是，这比平时花费了更长的时间。这时他意识到，他已经忘记了哪个终端被配置为指向哪个环境。（LCTT 译注：意即删除了生产环境。）</p><h3 id="故事之二" tabindex="-1">故事之二 <a class="header-anchor" href="#故事之二" aria-label="Permalink to “故事之二”">​</a></h3><p>第二个故事来自于一个商业的网页和手机应用。后端有一个由一组工程师负责的微服务体系结构。这意味着部署需要协调，但是使用正式的发布过程和自动化简化了一些。新代码在准备好后会被审查并合并到主干中，并且高层开发人员通常会为每个微服务标记版本，然后自动部署到临时环境。临时环境中的版本会被定期收集到一个元版本中，在自动部署到生产环境之前，该版本会得到各个人的签署（这是一个合规环境）。</p><p>有一天，一位开发人员正在开发一个复杂的功能，而其他开发该微服务的开发人员都同意将他们正在开发的代码提交到主干，也都知道它还不能被实际发布。长话短说，并不是团队中的每个人都收到了消息，而代码就进入了发布管道。更糟糕的是，那些实验性代码需要一种新的方式来表示用户配置文件数据，因此它有一个临时数据迁移，它在推出到生产环境时运行，损坏了所有的用户配置文件。</p><h3 id="故事之三" tabindex="-1">故事之三 <a class="header-anchor" href="#故事之三" aria-label="Permalink to “故事之三”">​</a></h3><p>第三个故事来自另一款网页应用。这个有一个更简单的架构：大部分代码在一个应用程序中，数据在数据库中。然而，这个应用程序也是在很大的截止日期压力下编写的。事实证明，在开发初期，当彻底更改的数据库架构很常见时，添加一项功能来检测此类更改并清理旧数据，这实际上对发布前的早期开发很有用，并且始终只是作为开发环境的临时功能。不幸的是，在匆忙构建应用的其余部分并推出时，我们忘记了这些代码。当然，直到有一天它在生产环境中被触发了。</p><h3 id="事后分析" tabindex="-1">事后分析 <a class="header-anchor" href="#事后分析" aria-label="Permalink to “事后分析”">​</a></h3><p>对于任何故障的事后分析，很容易忽视大局，最终将一切归咎于一些小细节。一个特例是发现某人犯了一些错误，然后责怪那个人。这些故事中的所有工程师实际上都是优秀的工程师（雇佣 SRE 顾问的公司不是那些在长期雇佣中偷工减料的公司），所以解雇他们，换掉他们并不能解决任何问题。即使你拥有 100 倍的开发人员，它仍然是有限的，所以在足够的复杂性和压力下，错误也会发生。最重要的解决方案是备份，无论你如何丢失数据（包括来自恶意软件，这是最近新闻中的一个热门话题），它都能帮助你。如果你无法容忍没有副本，就不要只有一个副本。</p><p>故事之一的结局很糟糕：没有备份。该项目的六个月的数据收集白干了。顺便说一句，有些地方只保留一个每日快照作为备份，这个故事也是一个很好的例子，说明了这也会出错：如果数据丢失发生在星期六，并且你准备在星期一尝试恢复，那么一日备份就只能得到星期日的一个空数据备份。</p><p>故事之二并不算好，但结果要好得多。备份是可用的，但数据迁移也是可逆的。不好的部分是发布是在推出前完成的，并且修复工作必须在生产站点关闭时进行编码。我讲这个故事的主要原因是为了提醒大家，备份并不仅仅是灾难性的数据丢失。部分数据损坏也会发生，而且可能会更加混乱。</p><p>故事之三还好。尽管少量数据永久丢失，但大部分数据可以从备份中恢复。团队中的每个人都对没有标记极其明显的危险代码感到非常难过。我没有参与早期的开发，但我感觉很糟糕，因为恢复数据所需的时间比正常情况要长得多。如果有一个经过良好测试的恢复过程，我认为该站点应该在总共不到 15 分钟的时间内重新上线。但是第一次恢复没有成功，我不得不调试它为什么不能成功，然后重试。当一个生产站点宕机了，需要你重新启动它，每过 10 秒钟都感觉过了一个世纪。值得庆幸的是，老板们比某些人更能理解我们。他们实际上松了一口气，因为这一场可能使公司沉没的一次性灾难只导致了几分钟的数据丢失和不到一个小时的停机时间。</p><p>在实践中，备份“成功”但恢复失败的情况极为普遍。很多时候，小型数据集上进行恢复测试是可以正常工作的，但在生产规模的大数据集上就会失败。当每个人都压力过大时，灾难最有可能发生，而生产站点的故障只会增加压力。在时间合适的时候测试和记录完整的恢复过程是一个非常好的主意。</p><hr>',19)),p("p",null,[t[1]||(t[1]=a("via: ",-1)),r(e,{href:"https://theartofmachinery.com/2021/06/06/how_apps_lose_data.html"},{default:o(()=>[...t[0]||(t[0]=[a("https://theartofmachinery.com/2021/06/06/how_apps_lose_data.html",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=a("作者：",-1)),r(e,{href:"https://theartofmachinery.com"},{default:o(()=>[...t[2]||(t[2]=[a("Simon Arneaud",-1)])]),_:1}),t[7]||(t[7]=a(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 译者：",-1)),r(e,{href:"https://github.com/PearFL"},{default:o(()=>[...t[4]||(t[4]=[a("PearFL",-1)])]),_:1}),t[9]||(t[9]=a(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=a("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[a("Linux中国",-1)])]),_:1}),t[14]||(t[14]=a(" 荣誉推出",-1))])])}const g=s(m,[["render",f]]);export{w as __pageData,g as default};
